// lib/konsistensiRulesM.ts
//
// Katalog 1.018 aturan konsistensi resmi BPS VSEN26.M (rule_expr disalin dari
// aplikasi desktop client, disimpan lengkap di Supabase kp_konsistensi_rules
// kuesioner='M' -- file ini adalah SALINAN statis yang sudah dianalisis
// kelayakan evaluasinya terhadap data yang benar-benar terekam aplikasi ini).
//
// evaluable=true  -> field yg dipakai rule_expr semuanya berhasil dipetakan
//                     ke kolom DBF asli (lihat konsistensiFieldMap.ts), siap
//                     dievaluasi lib/runKonsistensiPipeline.ts.
// evaluable=false -> TIDAK dievaluasi, dilewati apa adanya. Alasan ada di
//                     unsupported_reason: field GPS koordinat (tidak ada
//                     datanya sama sekali), rincian imunisasi/kesehatan
//                     balita Blok 8-9 (tidak terekam tabel m1 aplikasi ini),
//                     field referensi internal aplikasi desktop VSEN26
//                     (NuInfoBalita/NuInfoRT/NuInfoRT2 -- bukan bagian data
//                     ekspor), field BANR master data, satu field yang
//                     memang bolong di sumber data (M1612B), atau format
//                     rule_expr yang tidak umum.
//
// Cakupan saat file ini dibuat: 932/1.018 (91,6%) evaluable.

